SELECT cf.*, c.name AS courseName, u.fullname AS writerName, CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END AS isAttached, IFNULL(cc.comment_count, 0) AS commentCount, (SELECT COUNT(*) FROM course_forum_report cfr WHERE cfr.course_forum_id = cf.id AND cfr.report_status = 'RESOLVED') AS approvedReportCount FROM course_forum cf JOIN course c ON cf.course_id = c.id JOIN `user` u ON cf.writer_id = u.id LEFT JOIN (SELECT DISTINCT table_id FROM file WHERE table_name = 'course_forum' AND deleted_at IS NULL) f ON cf.id = f.table_id LEFT JOIN (SELECT course_forum_id, COUNT(id) AS comment_count FROM course_forum_comment WHERE deleted_at IS NULL GROUP BY course_forum_id) cc ON cf.id = cc.course_forum_id
cf.deleted_at IS NULL AND cf.is_hotpost = FALSE
AND c.is_in_progress = #{isInProgress}
AND cf.course_id = #{courseId}
AND cf.course_id IN
#{item}
AND
OR cf.title LIKE CONCAT('%', #{keyword}, '%')
OR cf.content LIKE CONCAT('%', #{keyword}, '%')
OR u.fullname LIKE CONCAT('%', #{keyword}, '%')
AND (CASE WHEN f.table_id IS NOT NULL THEN TRUE ELSE FALSE END) = #{hasAttachment}
AND c.name = #{courseName}
ORDER BY cf.is_hotpost DESC, CASE WHEN cf.is_hotpost = TRUE THEN cf.hotpost_at END DESC,
CASE WHEN cf.is_hotpost = FALSE THEN
commentCount cf.read_count cf.forum_like cf.title cf.created_at
END DESC,
CASE WHEN cf.is_hotpost = FALSE THEN
commentCount cf.read_count cf.forum_like cf.title cf.created_at
END ASC,
cf.id DESC LIMIT #{skip}, #{pagingSize}

